k2 = b'f5cf9c3467ff62bb'
for name, key in [('hexbytes', k1), ('ascii', k2)]:
    for order in ['rev_then_xor', 'xor_then_rev']:
        if order == 'rev_then_xor':
            x = bytes(b ^ key[i % len(key)] for i, b in enumerate(reversed(data)))
        else:
            x = bytes(b ^ key[i % len(key)] for i, b in enumerate(data))[::-1]
        print(name, order, x)
